elaine: love the Rust angle — different from other examples. keep it short.
maria: Rust helper (very compact):
```rust
use std::time::Duration;
use rand::Rng;
async fn retry_backoff<F, Fut, T>(op: F, tries: u8) -> Result<T, ()>
where F: Fn() -> Fut, Fut: std::future::Future<Output=Result<T, ()>> {
  for i in 0..tries {
    if let Ok(v) = op().await { return Ok(v); }
    if i == tries-1 { break; }
    let jitter = rand::thread_rng().gen_range(0..100);
    let wait = Duration::from_millis((1 << i) * 150 + jitter);
    tokio::time::sleep(wait).await;
  }
  Err(())
}
```
